import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Inicio from './components/Inicio';
import Programa from './components/Programa';
import GestionarParticipantes from './GestionarParticipantes';
import FiltrosAvanzados from './components/FiltrosAvanzados';
import Informes from './components/Informes';
import Planificador from './components/Planificador';
import AsignarAncMin from './components/AsignarAncMin';
import AcceptAssignments from './components/AcceptAssignments';
import HistorialEventos from './components/HistorialEventos';
import GrupoCongregacion from './components/GrupoCongregacion';

const App: React.FC = () => {
    const navItems = [
        "Inicio",
        "Programa",
        "Gestionar Participantes",
        "Grupo de Congregación",
        "Filtros Avanzados",
        "Respuestas de Asignaciones",
        "Informes",
        "Planificador",
        "Asignar Anc. y Min.",
    ];

    const [activeTab, setActiveTab] = useState<string>("Inicio");
    const [theme, setTheme] = useState<'light' | 'dark'>('light');
    const [viewMode, setViewMode] = useState<'desktop' | 'mobile'>('desktop');
    const [specialView, setSpecialView] = useState<{view: string; participant: string} | null>(null);

    useEffect(() => {
        const urlParams = new URLSearchParams(window.location.search);
        const view = urlParams.get('view');
        const participant = urlParams.get('participant');

        if (view === 'assignments' && participant) {
            setSpecialView({ view, participant: decodeURIComponent(participant) });
        } else {
            const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
            setTheme(prefersDark ? 'dark' : 'light');

            const isMobileDevice = () => /Mobi/i.test(window.navigator.userAgent) || window.innerWidth < 1024;
            setViewMode(isMobileDevice() ? 'mobile' : 'desktop');
        }
    }, []);

    const toggleTheme = () => {
        setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
    };

    const toggleViewMode = () => {
        setViewMode(prevMode => (prevMode === 'desktop' ? 'mobile' : 'desktop'));
    };

    const appClassName = `theme-${theme} view-${viewMode}`;

    if (specialView?.view === 'assignments') {
        return (
            <div className={`app-container ${appClassName}`}>
                <AcceptAssignments participant={specialView.participant} />
            </div>
        );
    }

    return (
        <div className={`app-container ${appClassName}`}>
            <Header
                navItems={navItems}
                activeTab={activeTab}
                setActiveTab={setActiveTab}
                theme={theme}
                toggleTheme={toggleTheme}
                viewMode={viewMode}
                toggleViewMode={toggleViewMode}
            />
            <main>
                <div style={{ display: activeTab === 'Inicio' ? 'block' : 'none' }}><Inicio /></div>
                <div style={{ display: activeTab === 'Programa' ? 'block' : 'none' }}><Programa /></div>
                <div style={{ display: activeTab === 'Gestionar Participantes' ? 'block' : 'none' }}><GestionarParticipantes /></div>
                <div style={{ display: activeTab === 'Grupo de Congregación' ? 'block' : 'none' }}><GrupoCongregacion /></div>
                <div style={{ display: activeTab === 'Filtros Avanzados' ? 'block' : 'none' }}><FiltrosAvanzados /></div>
                <div style={{ display: activeTab === 'Respuestas de Asignaciones' ? 'block' : 'none' }}><HistorialEventos /></div>
                <div style={{ display: activeTab === 'Informes' ? 'block' : 'none' }}><Informes /></div>
                <div style={{ display: activeTab === 'Planificador' ? 'block' : 'none' }}><Planificador /></div>
                <div style={{ display: activeTab === 'Asignar Anc. y Min.' ? 'block' : 'none' }}><AsignarAncMin /></div>
            </main>
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

// Map of publisher_name -> Report
type ReportsMap = Record<string, MinistryReport>;
// Map of publisher_name -> Date string
type VisitsMap = Record<string, string>;

const GrupoCongregacion: React.FC = () => {
    const [publishers, setPublishers] = useState<Publisher[]>([]);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

    // Initialize month to current month YYYY-MM
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);
    }, []);

    // Load Publishers
    useEffect(() => {
        const fetchPublishers = async () => {
            setLoading(true);
            const { data, error } = await supabase
                .from('publicadores')
                .select('id, nombre')
                .order('nombre');

            if (error) {
                console.error('Error loading publishers:', error);
            } else {
                setPublishers(data || []);
            }
            setLoading(false);
        };
        fetchPublishers();
    }, []);

    // Load Reports and Visits when month or publishers change
    useEffect(() => {
        if (!currentMonth || publishers.length === 0) return;

        const fetchData = async () => {
            // Fetch Reports for current month
            // Note: Assuming table 'informes_ministerio' exists. 
            // Structure: id, publicador_nombre, mes (YYYY-MM), horas
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            // Fetch Visits (Last visit date)
            // Note: Assuming table 'visitas_pastoral' exists.
            // Structure: id, publicador_nombre, fecha_visita
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita');

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, publishers]);

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // Save Report
            const reportVal = reports[publisherName]?.horas;
            if (reportVal !== undefined && reportVal !== '') {
                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: reportVal 
                    }, { onConflict: 'publicador_nombre, mes' });

                if (reportError) throw reportError;
            }

            // Save Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                // We typically want to store the *latest* visit. 
                // Simple upsert by publisher name if we only track the latest, 
                // or insert new if tracking history. Here assuming latest per publisher for simplicity in this view.
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });

                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado correctamente', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);

        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const filteredPublishers = publishers.filter(p => 
        p.nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="container mx-auto px-4 py-8 group-container">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold text-gray-800">Grupo de Congregación</h2>

                <div className="flex gap-4 items-center bg-white p-3 rounded-lg shadow-sm border border-gray-200">
                    <label className="font-semibold text-gray-600">Mes del Informe:</label>
                    <input 
                        type="month" 
                        value={currentMonth} 
                        onChange={(e) => setCurrentMonth(e.target.value)}
                        className="p-2 border rounded-md"
                    />
                </div>
            </div>

            <div className="search-box mb-6 max-w-md">
                <div className="relative">
                    <i className="fas fa-search absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                    <input 
                        type="text" 
                        placeholder="Buscar publicador..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                </div>
            </div>

            {statusMessage && (
                <div className={`mb-4 p-3 rounded text-center font-semibold ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                    {statusMessage.text}
                </div>
            )}

            {loading ? (
                <div className="text-center p-8 text-gray-500">Cargando datos...</div>
            ) : (
                <div className="bg-white shadow rounded-lg overflow-hidden border border-gray-200">
                    <div className="hidden md:grid grid-cols-12 bg-gray-50 border-b border-gray-200 p-4 font-semibold text-gray-600 text-sm uppercase tracking-wider">
                        <div className="col-span-4">Publicador</div>
                        <div className="col-span-3 text-center">Horas ({currentMonth})</div>
                        <div className="col-span-3 text-center">Visita de Ánimo</div>
                        <div className="col-span-2 text-center">Acción</div>
                    </div>

                    <div className="divide-y divide-gray-100">
                        {filteredPublishers.map(p => {
                            const hasReport = reports[p.nombre]?.horas !== undefined && reports[p.nombre]?.horas !== '';
                            const visitDate = visits[p.nombre] || '';

                            // Calculate days since last visit for visual cue
                            let visitStatusColor = 'text-gray-400';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) visitStatusColor = 'text-green-500'; // Recent
                                else if (daysSince < 180) visitStatusColor = 'text-yellow-500'; // Warning
                                else visitStatusColor = 'text-red-500'; // Needs visit
                            }

                            return (
                                <div key={p.id} className="grid grid-cols-1 md:grid-cols-12 p-4 gap-4 items-center hover:bg-gray-50 transition-colors">
                                    <div className="col-span-1 md:col-span-4 font-medium text-gray-800 flex items-center gap-2">
                                        <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-sm font-bold">
                                            {p.nombre.charAt(0)}
                                        </div>
                                        {p.nombre}
                                    </div>

                                    <div className="col-span-1 md:col-span-3 flex justify-between md:justify-center items-center gap-2">
                                        <span className="md:hidden text-sm text-gray-500">Horas:</span>
                                        <div className="relative w-24">
                                            <input 
                                                type="number" 
                                                min="0"
                                                value={reports[p.nombre]?.horas ?? ''}
                                                onChange={(e) => handleReportChange(p.nombre, e.target.value)}
                                                className={`w-full p-2 border rounded text-center font-mono focus:ring-2 focus:ring-blue-500 outline-none ${hasReport ? 'border-green-300 bg-green-50' : 'border-gray-300'}`}
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>

                                    <div className="col-span-1 md:col-span-3 flex justify-between md:justify-center items-center gap-2">
                                        <span className="md:hidden text-sm text-gray-500">Visita:</span>
                                        <div className="relative flex items-center gap-2">
                                            <i className={`fas fa-circle text-xs ${visitStatusColor}`} title="Estado de visita"></i>
                                            <input 
                                                type="date" 
                                                value={visitDate}
                                                onChange={(e) => handleVisitChange(p.nombre, e.target.value)}
                                                className="p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                            />
                                        </div>
                                    </div>

                                    <div className="col-span-1 md:col-span-2 text-center md:text-right">
                                        <button 
                                            onClick={() => handleSaveRow(p.nombre)}
                                            className="w-full md:w-auto bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded shadow-sm transition-all active:transform active:scale-95"
                                        >
                                            <i className="fas fa-save md:mr-0"></i> <span className="md:hidden ml-2">Guardar</span>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredPublishers.length === 0 && (
                        <div className="p-8 text-center text-gray-500 italic">
                            No se encontraron publicadores.
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

// Map of publisher_name -> Report
type ReportsMap = Record<string, MinistryReport>;
// Map of publisher_name -> Date string
type VisitsMap = Record<string, string>;

const GrupoCongregacion: React.FC = () => {
    const [publishers, setPublishers] = useState<Publisher[]>([]);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [newPublisherName, setNewPublisherName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

    // Initialize month to current month YYYY-MM
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);
    }, []);

    // Load Publishers
    const fetchPublishers = async () => {
        setLoading(true);
        const { data, error } = await supabase
            .from('publicadores')
            .select('id, nombre')
            .order('nombre');

        if (error) {
            console.error('Error loading publishers:', error);
        } else {
            setPublishers(data || []);
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchPublishers();
    }, []);

    // Load Reports and Visits when month or publishers change
    useEffect(() => {
        if (!currentMonth) return;

        const fetchData = async () => {
            // Fetch Reports for current month
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            // Fetch Visits (Last visit date)
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita');

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, publishers.length]); // Reload when publisher count changes too

    const handleAddPublisher = async () => {
        if (!newPublisherName.trim()) return;

        try {
            const { error } = await supabase
                .from('publicadores')
                .insert([{ nombre: newPublisherName.trim() }]);

            if (error) throw error;

            setStatusMessage({ text: 'Publicador agregado', type: 'success' });
            setNewPublisherName('');
            fetchPublishers(); // Reload list
            setTimeout(() => setStatusMessage(null), 3000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al agregar', type: 'error' });
        }
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // Save Report
            const reportVal = reports[publisherName]?.horas;
            if (reportVal !== undefined && reportVal !== '') {
                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: reportVal 
                    }, { onConflict: 'publicador_nombre, mes' });

                if (reportError) throw reportError;
            }

            // Save Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });

                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado correctamente', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);

        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar (Verifica que las tablas existan en Supabase)', type: 'error' });
        }
    };

    const filteredPublishers = publishers.filter(p => 
        p.nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="container mx-auto px-4 py-8 group-container">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold text-gray-800">Grupo de Congregación</h2>

