                        type="text" 
                        value={newPublisherName}
                        onChange={(e) => setNewPublisherName(e.target.value)}
                        placeholder="Nombre completo"
                        className="w-full p-2 border border-blue-200 rounded focus:ring-2 focus:ring-blue-500 outline-none"
