                    <i className="fas fa-search absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                    <input 
                        type="text" 
                        placeholder="Buscar en la lista..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                </div>
            </div>

            {statusMessage && (
                <div className={`mb-4 p-3 rounded text-center font-semibold ${statusMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                    {statusMessage.text}
                </div>
            )}

            {loading ? (
                <div className="text-center p-8 text-gray-500">Cargando datos...</div>
            ) : (
                <div className="bg-white shadow rounded-lg overflow-hidden border border-gray-200">
                    <div className="hidden md:grid grid-cols-12 bg-gray-50 border-b border-gray-200 p-4 font-semibold text-gray-600 text-sm uppercase tracking-wider">
                        <div className="col-span-4">Publicador</div>
                        <div className="col-span-3 text-center">Horas ({currentMonth})</div>
                        <div className="col-span-3 text-center">Visita de Ánimo</div>
                        <div className="col-span-2 text-center">Acción</div>
                    </div>

                    <div className="divide-y divide-gray-100">
                        {filteredPublishers.map(p => {
                            const hasReport = reports[p.nombre]?.horas !== undefined && reports[p.nombre]?.horas !== '';
