                                            />
                                        </div>
                                    </div>

                                    <div className="col-span-1 md:col-span-3 flex justify-between md:justify-center items-center gap-2">
                                        <span className="md:hidden text-sm text-gray-500">Visita:</span>
                                        <div className="relative flex items-center gap-2 w-full md:w-auto">
                                            <i className={`fas fa-circle text-xs ${visitStatusColor} hidden md:block`} title={visitTitle}></i>
                                            <input 
                                                type="date" 
                                                value={visitDate}
                                                onChange={(e) => handleVisitChange(p.nombre, e.target.value)}
                                                className="p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none w-full"
                                            />
                                        </div>
                                    </div>

                                    <div className="col-span-1 md:col-span-2 text-center md:text-right">
                                        <button 
                                            onClick={() => handleSaveRow(p.nombre)}
                                            className="w-full md:w-auto bg-white border border-blue-600 text-blue-600 hover:bg-blue-50 px-4 py-2 rounded shadow-sm transition-all active:transform active:scale-95 text-sm font-semibold"
                                        >
                                            <i className="fas fa-save md:mr-0"></i> <span className="md:hidden ml-2">Guardar</span>
