import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

// Map of publisher_name -> Report
type ReportsMap = Record<string, MinistryReport>;
// Map of publisher_name -> Date string
type VisitsMap = Record<string, string>;

const GrupoCongregacion: React.FC = () => {
    const [publishers, setPublishers] = useState<Publisher[]>([]);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [newPublisherName, setNewPublisherName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

    // Initialize month to current month YYYY-MM
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);
    }, []);

    // Load Publishers from the dedicated group table
    const fetchPublishers = async () => {
        setLoading(true);
        // Changed to 'integrantes_grupo' to keep it empty initially/isolated
        const { data, error } = await supabase
            .from('integrantes_grupo')
            .select('id, nombre')
            .order('nombre');

        if (error) {
            console.error('Error loading publishers:', error);
        } else {
            setPublishers(data || []);
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchPublishers();
    }, []);

    // Load Reports and Visits
    useEffect(() => {
        if (!currentMonth) return;

        const fetchData = async () => {
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita');

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, publishers.length]);

    const handleAddPublisher = async () => {
        if (!newPublisherName.trim()) return;

        try {
            const { error } = await supabase
                .from('integrantes_grupo')
                .insert([{ nombre: newPublisherName.trim() }]);

            if (error) throw error;

            setStatusMessage({ text: 'Publicador agregado', type: 'success' });
            setNewPublisherName('');
            fetchPublishers();
            setTimeout(() => setStatusMessage(null), 3000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al agregar (¿Nombre duplicado?)', type: 'error' });
        }
    };

    const handleDeletePublisher = async (id: number, name: string) => {
        if (!window.confirm(`¿Estás seguro de eliminar a ${name} del grupo?`)) return;

        try {
            const { error } = await supabase
                .from('integrantes_grupo')
                .delete()
                .eq('id', id);

            if (error) throw error;
            fetchPublishers();
        } catch (err) {
            console.error(err);
            alert('Error al eliminar');
        }
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // Save Report
            const reportVal = reports[publisherName]?.horas;
            if (reportVal !== undefined && reportVal !== '') {
                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: reportVal 
                    }, { onConflict: 'publicador_nombre, mes' });

                if (reportError) throw reportError;
            }

            // Save Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });

                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);

        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const filteredPublishers = publishers.filter(p => 
        p.nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="container mx-auto px-4 py-8 group-container">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4 border-b pb-4">
                <div>
                    <h2 className="text-3xl font-bold text-gray-800">Grupo de Congregación N° 5</h2>
                    <p className="text-gray-500 text-sm mt-1">{publishers.length} Publicadores registrados</p>
                </div>

                <div className="flex gap-4 items-center bg-white p-2 rounded-lg shadow-sm border border-gray-200">
                    <label className="font-semibold text-gray-600 px-2">Informe:</label>
                    <input 
                        type="month" 
                        value={currentMonth} 
                        onChange={(e) => setCurrentMonth(e.target.value)}
                        className="p-2 border rounded-md font-medium text-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>
            </div>

            {/* Add Publisher Section */}
            <div className="bg-gradient-to-r from-blue-50 to-white p-5 rounded-xl border border-blue-100 mb-8 shadow-sm">
                <h3 className="text-sm font-bold text-blue-800 uppercase tracking-wide mb-3">Agregar Nuevo Integrante</h3>
                <div className="flex flex-col sm:flex-row gap-3">
                    <input 
                        type="text" 
                        value={newPublisherName}
                        onChange={(e) => setNewPublisherName(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleAddPublisher()}
                        placeholder="Nombre completo del publicador"
                        className="flex-grow p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                    />
                    <button 
                        onClick={handleAddPublisher}
                        disabled={!newPublisherName.trim()}
                        className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg transition-all shadow-md active:transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        <i className="fas fa-user-plus mr-2"></i> Agregar
                    </button>
                </div>
            </div>

            {/* Search */}
            {publishers.length > 0 && (
                <div className="mb-6 max-w-md ml-auto">
                    <div className="relative">
                        <i className="fas fa-search absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                        <input 
                            type="text" 
                            placeholder="Filtrar lista..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white"
                        />
                    </div>
                </div>
            )}

            {statusMessage && (
                <div className={`fixed bottom-4 right-4 z-50 p-4 rounded-lg shadow-lg font-semibold animate-bounce ${statusMessage.type === 'success' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'}`}>
                    {statusMessage.type === 'success' ? <i className="fas fa-check-circle mr-2"></i> : <i className="fas fa-exclamation-circle mr-2"></i>}
                    {statusMessage.text}
                </div>
            )}

            {loading ? (
                <div className="text-center p-12 text-gray-500">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando lista...</p>
                </div>
            ) : (
                <div className="bg-white shadow-lg rounded-xl overflow-hidden border border-gray-200">
                    <div className="hidden md:grid grid-cols-12 bg-gray-100 border-b border-gray-200 p-4 font-bold text-gray-700 text-sm uppercase tracking-wider">
                        <div className="col-span-1 text-center">#</div>
                        <div className="col-span-4">Publicador</div>
                        <div className="col-span-2 text-center">Horas</div>
                        <div className="col-span-3 text-center">Última Visita</div>
                        <div className="col-span-2 text-center">Acciones</div>
                    </div>

                    <div className="divide-y divide-gray-100">
                        {filteredPublishers.map((p, index) => {
                            const hasReport = reports[p.nombre]?.horas !== undefined && reports[p.nombre]?.horas !== '';
                            const visitDate = visits[p.nombre] || '';

                            // Visual cue for visits
                            let visitStatusColor = 'text-gray-300';
                            let visitTitle = 'Sin visita registrada';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitStatusColor = 'text-green-500'; visitTitle = 'Visita reciente'; }
                                else if (daysSince < 180) { visitStatusColor = 'text-yellow-500'; visitTitle = 'Atención requerida'; }
                                else { visitStatusColor = 'text-red-500'; visitTitle = 'Visita urgente'; }
                            }

                            return (
                                <div key={p.id} className="grid grid-cols-1 md:grid-cols-12 p-4 gap-4 items-center hover:bg-gray-50 transition-colors group">
                                    <div className="hidden md:block col-span-1 text-center text-gray-400 font-mono text-sm">
                                        {index + 1}
                                    </div>
                                    <div className="col-span-1 md:col-span-4 font-medium text-gray-800 flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-lg font-bold shadow-sm">
                                            {p.nombre.charAt(0)}
                                        </div>
                                        <span className="text-lg">{p.nombre}</span>
                                    </div>

                                    <div className="col-span-1 md:col-span-2 flex md:justify-center items-center gap-3">
                                        <span className="md:hidden text-gray-500 w-24">Horas:</span>
                                        <input 
                                            type="number" 
                                            min="0"
                                            step="0.5"
                                            value={reports[p.nombre]?.horas ?? ''}
                                            onChange={(e) => handleReportChange(p.nombre, e.target.value)}
                                            className={`w-24 p-2 border-2 rounded-lg text-center font-bold text-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all ${hasReport ? 'border-green-400 bg-green-50 text-green-800' : 'border-gray-200 focus:border-blue-400'}`}
                                            placeholder="-"
                                        />
                                    </div>

                                    <div className="col-span-1 md:col-span-3 flex md:justify-center items-center gap-3">
                                        <span className="md:hidden text-gray-500 w-24">Visita:</span>
                                        <div className="relative flex items-center w-full md:w-auto">
                                            <i className={`fas fa-circle text-xs ${visitStatusColor} absolute left-3 z-10`} title={visitTitle}></i>
                                            <input 
                                                type="date" 
                                                value={visitDate}
                                                onChange={(e) => handleVisitChange(p.nombre, e.target.value)}
                                                className="w-full pl-8 p-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                            />
                                        </div>
                                    </div>

                                    <div className="col-span-1 md:col-span-2 flex justify-end md:justify-center gap-2">
                                        <button 
                                            onClick={() => handleSaveRow(p.nombre)}
                                            className="bg-blue-600 hover:bg-blue-700 text-white w-10 h-10 rounded-full shadow-md flex items-center justify-center transition-transform active:scale-90"
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i>
                                        </button>
                                        <button 
                                            onClick={() => handleDeletePublisher(p.id, p.nombre)}
                                            className="bg-white border border-red-200 text-red-500 hover:bg-red-50 w-10 h-10 rounded-full flex items-center justify-center transition-colors"
                                            title="Eliminar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredPublishers.length === 0 && (
                        <div className="py-16 text-center">
                            <div className="bg-gray-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-400">
                                <i className="fas fa-users fa-2x"></i>
                            </div>
                            <h3 className="text-xl font-medium text-gray-600">Tu lista está vacía</h3>
                            <p className="text-gray-500 mt-2">Agrega a los 22 publicadores de tu grupo usando el formulario de arriba.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

