### Instrucciones SQL Actualizadas (Obligatorio)

Copia y pega esto en el **Editor SQL de Supabase** para crear la tabla nueva `integrantes_grupo` y asegurarte de que las tablas de informes funcionen con ella.

```sql
-- 1. Tabla NUEVA y EXCLUSIVA para tu Grupo 5
CREATE TABLE IF NOT EXISTS integrantes_grupo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre TEXT NOT NULL UNIQUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Tabla para guardar las horas (si no la creaste antes)
CREATE TABLE IF NOT EXISTS informes_ministerio (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    publicador_nombre TEXT NOT NULL,
    mes TEXT NOT NULL, -- Formato 'YYYY-MM'
    horas NUMERIC,
    notas TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    UNIQUE(publicador_nombre, mes) -- Evita duplicados por mes
);

-- 3. Tabla para visitas (si no la creaste antes)
CREATE TABLE IF NOT EXISTS visitas_pastoral (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    publicador_nombre TEXT NOT NULL UNIQUE,
    fecha_visita DATE,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 4. Habilitar seguridad (Opcional, recomendado)
ALTER TABLE integrantes_grupo ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Acceso total grupo" ON integrantes_grupo FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE informes_ministerio ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Acceso total informes" ON informes_ministerio FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE visitas_pastoral ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Acceso total visitas" ON visitas_pastoral FOR ALL USING (true) WITH CHECK (true);

