                </div>
                <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap' }}>
                    <div style={{ position: 'relative', flexGrow: 1 }}>
                        <i className="fas fa-user" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af' }}></i>
                        <input 
                            type="text" 
                            value={newPublisherName}
                            onChange={(e) => setNewPublisherName(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAddPublisher()}
                            placeholder="Nombre completo del publicador"
                            className="gc-input-add"
