                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            const isPredicado = String(currentVal || '').toLowerCase() === 'si';

                            return (
                                <div key={m.id} className="group-member-card flex flex-col md:grid md:grid-cols-12 md:gap-4 md:items-center" style={{ 
                                    padding: '1.25rem', borderBottom: '1px solid #f1f5f9', backgroundColor: 'white', transition: 'background-color 0.2s'
                                }}>

                                    {/* Name */}
                                    <div className="md:col-span-4 flex items-center gap-3 mb-3 md:mb-0">
                                        <div className={`modern-avatar shadow-md ${getAvatarClass(pName)}`}>
                                            {pName.charAt(0).toUpperCase()}
                                        </div>
                                        <div style={{ fontWeight: '600', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                    </div>

                                    {/* Hours Section - Vertical on Mobile, Centered on Desktop */}
                                    <div className="md:col-span-3 flex flex-col gap-1 mb-3 md:mb-0 md:items-center">
                                        <label className="text-xs font-bold text-gray-400 uppercase md:hidden tracking-wider mb-1">Horas del mes</label>
                                        <div className="flex items-center gap-3">
                                            <button 
                                                onClick={() => togglePreached(pName)}
                                                style={{
                                                    padding: '0.5rem 0.75rem',
                                                    borderRadius: '0.5rem',
                                                    border: isPredicado ? '1px solid #34d399' : '1px solid #e5e7eb',
                                                    backgroundColor: isPredicado ? '#ecfdf5' : 'white',
                                                    color: isPredicado ? '#059669' : '#6b7280',
                                                    cursor: 'pointer',
                                                    fontSize: '0.85rem',
                                                    fontWeight: '600',
                                                    transition: 'all 0.2s',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '0.25rem'
                                                }}
                                                title='Marcar como "si" (Predicó)'
                                            >
                                                {isPredicado ? <i className="fas fa-check"></i> : <i className="fas fa-bullhorn"></i>}
                                                <span>Predicó</span>
                                            </button>
                                            <input 
                                                type="text" 
                                                value={reports[pName]?.horas ?? ''}
                                                onChange={(e) => handleReportChange(pName, e.target.value)}
                                                className={hasReport ? 'input-has-report' : ''}
                                                style={{ 
                                                    width: '5rem', padding: '0.5rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.5rem', 
                                                    border: hasReport ? '2px solid #34d399' : '1px solid #e5e7eb', outline: 'none', transition: 'all 0.2s', color: '#4b5563'
                                                }}
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>

                                    {/* Visit Section - Vertical on Mobile, Centered on Desktop */}
                                    <div className="md:col-span-3 flex flex-col gap-1 mb-3 md:mb-0 md:items-center">
                                        <label className="text-xs font-bold text-gray-400 uppercase md:hidden tracking-wider mb-1">Visita de Pastoreo</label>
                                        <div className="flex items-center gap-2 w-full md:w-auto md:justify-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.4rem', fontSize: '0.875rem', color: '#4b5563', fontWeight: '500', borderRadius: '0.5rem', border: '1px solid #e5e7eb' }}
                                            />
                                            <span className={visitBadgeClass} style={{fontSize: '0.7rem', padding: '0.1rem 0.4rem', whiteSpace: 'nowrap'}}>
                                                {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div className="md:col-span-2 flex justify-end gap-3 mt-1 md:mt-0 md:justify-center">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem', fontWeight: '600', boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span>Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.5rem 0.75rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid #e5e7eb', borderRadius: '0.5rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.borderColor = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.borderColor = '#e5e7eb'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); // Stores last visit date

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            // Like: 2024-01, 2024-02...
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); // Filter by year prefix

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas // Database handles string/number conversion or logic usually, make sure DB accepts text if 'si' is allowed, or handle logic here
            })).filter(r => r.horas !== ''); // Only save non-empty

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions (Create Group, Add Member, etc. - mostly same as before)
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    // Helper to generate the PDF report (Mock function for now)
    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
        // Here you would integrate jsPDF or similar to generate the S-21 form
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">

                {/* Group Selector */}
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-blue-700 pr-8 cursor-pointer focus:outline-none"
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-blue-400 pointer-events-none text-sm"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 hover:bg-indigo-200 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-full bg-red-100 text-red-600 hover:bg-red-200 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border rounded px-2 py-1 text-sm" />
                            <button onClick={handleCreateGroup} className="bg-green-500 text-white px-3 py-1 rounded text-sm">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-400 text-white px-3 py-1 rounded text-sm">X</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm font-medium mt-1 flex items-center gap-2">
                        <i className="fas fa-users text-blue-400"></i> {members.length} Publicadores
                    </p>
                </div>

                {/* Annual & Report Controls */}
                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">

                    {/* Report Download Section */}
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-bold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-600 hover:text-blue-600 ml-1" title="Descargar reporte de este mes">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    {/* Year Selector */}
                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600"><i className="fas fa-chevron-right"></i></button>
