            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador (Buscar o escribir nuevo)..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2 hover:bg-gray-50 cursor-pointer flex items-center gap-3 border-b border-gray-100 last:border-0">
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs text-white font-bold ${getAvatarClass(p.nombre)}`}>{p.nombre.charAt(0)}</div>
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus ml-auto text-green-500 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-sm"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-6 py-3 rounded-lg shadow-lg text-white font-semibold flex items-center gap-3 z-50 animate-fade-in-up ${statusMessage.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check' : 'fa-exclamation-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    <th className="py-3 px-4 font-bold text-gray-700 sticky left-0 bg-gray-50 z-10 w-48 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-semibold text-gray-600 w-16 border-l border-gray-100">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-bold text-gray-700 border-l border-gray-200 w-32 bg-gray-50">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16 bg-gray-50"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = 'text-gray-400';
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = 'text-green-500';
                                        else if (daysSince < 180) visitColor = 'text-yellow-500';
                                        else visitColor = 'text-red-500';
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-blue-50/30 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2 px-4 sticky left-0 bg-white group-hover:bg-blue-50/30 z-10 border-r border-gray-100 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs text-white font-bold shadow-sm ${getAvatarClass(pName)}`}>
                                                        {pName.charAt(0)}
                                                    </div>
                                                    <span className="font-semibold text-gray-800 truncate max-w-[140px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const isSi = val.toLowerCase() === 'si';
                                                const isNum = val !== '' && !isNaN(Number(val));

                                                let cellBg = '';
                                                if (isSi) cellBg = 'bg-green-50 text-green-700 font-bold border-green-200';
                                                else if (isNum) cellBg = 'bg-blue-50 text-blue-700 font-bold border-blue-200';

                                                return (
                                                    <td key={month.id} className="p-1 border-l border-gray-100 text-center">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className={`w-full text-center py-1.5 rounded text-sm focus:ring-2 focus:ring-blue-400 focus:outline-none border border-transparent hover:border-gray-200 transition-all ${cellBg}`}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/30">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className={`w-full bg-transparent text-xs font-medium text-right focus:outline-none ${visitColor}`}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-end text-gray-300 text-xs pr-2">---</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center bg-gray-50/30">
                                                <div className="flex justify-center gap-2 opacity-30 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:bg-blue-100 p-1.5 rounded" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-12 text-center bg-gray-50">
                            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-bold text-gray-700">Grupo Vacío</h3>
                            <p className="text-gray-500">Agrega publicadores para ver la hoja de registro anual.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); // Stores last visit date

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            // Like: 2024-01, 2024-02...
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); // Filter by year prefix

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas // Database handles string/number conversion or logic usually, make sure DB accepts text if 'si' is allowed, or handle logic here
            })).filter(r => r.horas !== ''); // Only save non-empty

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions (Create Group, Add Member, etc. - mostly same as before)
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    // Helper to generate the PDF report (Mock function for now)
    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
        // Here you would integrate jsPDF or similar to generate the S-21 form
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">

                {/* Group Selector */}
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                {/* Annual & Report Controls */}
                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">

                    {/* Report Download Section */}
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    {/* Year Selector */}
                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up ${statusMessage.type === 'success' ? 'bg-emerald-600' : (statusMessage.type === 'info' ? 'bg-blue-600' : 'bg-red-600')}`}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    <th className="py-3 px-4 font-semibold text-gray-600 sticky left-0 bg-gray-50 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-200">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-medium text-gray-500 w-16 border-r border-gray-100 last:border-r-0">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-semibold text-gray-600 border-l border-gray-200 w-32 bg-gray-50">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16 bg-gray-50"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = 'text-gray-400';
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = 'text-emerald-600 font-medium';
                                        else if (daysSince < 180) visitColor = 'text-amber-600 font-medium';
                                        else visitColor = 'text-red-500 font-medium';
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-gray-50 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-gray-50 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.02)]">
                                                <div className="flex items-center">
                                                    <span className="font-medium text-gray-900 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const isSi = val.toLowerCase() === 'si';
                                                const isNum = val !== '' && !isNaN(Number(val));

                                                let cellClass = 'text-gray-600';
                                                if (isSi) cellClass = 'text-emerald-600 font-bold bg-emerald-50/50';
                                                else if (isNum) cellClass = 'text-blue-600 font-semibold bg-blue-50/30';

                                                return (
                                                    <td key={month.id} className="p-0 border-r border-gray-100 last:border-r-0">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className={`w-full h-full text-center py-2.5 bg-transparent focus:bg-white focus:ring-2 focus:ring-inset focus:ring-blue-500 outline-none transition-all ${cellClass}`}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/30">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className={`w-full bg-transparent text-xs text-right focus:outline-none cursor-pointer ${visitColor}`}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center bg-gray-50/30">
                                                <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:bg-blue-100 p-1.5 rounded transition-colors" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-gray-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded transition-colors" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); // Stores last visit date

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            // Like: 2024-01, 2024-02...
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); // Filter by year prefix

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas // Database handles string/number conversion or logic usually, make sure DB accepts text if 'si' is allowed, or handle logic here
            })).filter(r => r.horas !== ''); // Only save non-empty

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions (Create Group, Add Member, etc. - mostly same as before)
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    // Helper to generate the PDF report (Mock function for now)
    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
        // Here you would integrate jsPDF or similar to generate the S-21 form
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">

                {/* Group Selector */}
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                    style={{border: 'none', background: 'transparent'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                {/* Annual & Report Controls */}
                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">

                    {/* Report Download Section */}
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    {/* Year Selector */}
                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    <th className="py-3 px-4 font-semibold text-gray-600 sticky left-0 bg-gray-50 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-200 uppercase text-xs tracking-wider">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-medium text-gray-500 w-16 border-r border-gray-100 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-semibold text-gray-600 border-l border-gray-200 w-32 bg-gray-50 uppercase text-xs tracking-wider">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16 bg-gray-50"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = '#059669'; // emerald-600
                                        else if (daysSince < 180) visitColor = '#d97706'; // amber-600
                                        else visitColor = '#dc2626'; // red-600
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-gray-50 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-gray-50 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-medium text-gray-900 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val !== '' && !isNaN(Number(val));

                                                // Default style
                                                let cellStyle: React.CSSProperties = {
                                                    color: '#4b5563', // gray-600
                                                    backgroundColor: 'transparent'
                                                };

                                                if (isSi) {
                                                    cellStyle = {
                                                        backgroundColor: '#d1fae5', // emerald-100
                                                        color: '#065f46', // emerald-800
                                                        fontWeight: 'bold'
                                                    };
                                                } else if (isNum) {
                                                    cellStyle = {
                                                        backgroundColor: '#dbeafe', // blue-100
                                                        color: '#1e40af', // blue-800
                                                        fontWeight: '600'
                                                    };
                                                }

                                                return (
                                                    <td key={month.id} className="p-0 border-r border-gray-100 last:border-r-0">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className="w-full h-full text-center py-2.5 outline-none transition-all"
                                                            style={cellStyle}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/30">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="w-full bg-transparent text-xs text-right focus:outline-none cursor-pointer"
                                                        style={{color: visitColor, fontWeight: '500'}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center bg-gray-50/30">
                                                <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:bg-blue-100 p-1.5 rounded transition-colors" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-gray-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded transition-colors" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                    style={{border: 'none', background: 'transparent'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    <th className="py-3 px-4 font-semibold text-gray-600 sticky left-0 bg-gray-50 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-200 uppercase text-xs tracking-wider">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-medium text-gray-500 w-16 border-r border-gray-100 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-semibold text-gray-600 border-l border-gray-200 w-32 bg-gray-50 uppercase text-xs tracking-wider">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16 bg-gray-50"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = '#059669'; // emerald-600
                                        else if (daysSince < 180) visitColor = '#d97706'; // amber-600
                                        else visitColor = '#dc2626'; // red-600
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-gray-50 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-gray-50 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-medium text-gray-900 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val !== '' && !isNaN(Number(val));

                                                // INLINE STYLES FOR GUARANTEED COLOR
                                                let cellStyle: React.CSSProperties = {
                                                    color: '#4b5563', // default gray-600
                                                    backgroundColor: 'transparent',
                                                    fontWeight: 'normal'
                                                };

                                                if (isSi) {
                                                    cellStyle = {
                                                        backgroundColor: '#d1fae5', // emerald-100
                                                        color: '#065f46', // emerald-800
                                                        fontWeight: 'bold'
                                                    };
                                                } else if (isNum) {
                                                    cellStyle = {
                                                        backgroundColor: '#dbeafe', // blue-100
                                                        color: '#1e40af', // blue-800
                                                        fontWeight: 'bold'
                                                    };
                                                }

                                                return (
                                                    <td key={month.id} className="p-0 border-r border-gray-100 last:border-r-0">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className="w-full h-full text-center py-2.5 outline-none transition-all"
                                                            style={cellStyle}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/30">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="w-full bg-transparent text-xs text-right focus:outline-none cursor-pointer"
                                                        style={{color: visitColor, fontWeight: 'bold'}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center bg-gray-50/30">
                                                <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:bg-blue-100 p-1.5 rounded transition-colors" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-gray-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded transition-colors" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                    style={{border: 'none', background: 'transparent'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead style={{backgroundColor: '#f1f5f9', color: '#334155'}}>
                                <tr className="border-b border-gray-200">
                                    <th className="py-3 px-4 font-semibold sticky left-0 bg-gray-50 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)] border-r border-gray-200 uppercase text-xs tracking-wider" style={{backgroundColor: '#f8fafc'}}>
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-medium w-16 border-r border-gray-200 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-semibold border-l border-gray-200 w-32 uppercase text-xs tracking-wider" style={{backgroundColor: '#f8fafc'}}>
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16" style={{backgroundColor: '#f8fafc'}}></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = '#059669'; // emerald-600
                                        else if (daysSince < 180) visitColor = '#d97706'; // amber-600
                                        else visitColor = '#dc2626'; // red-600
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-gray-50 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-gray-50 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-medium text-gray-900 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // INLINE STYLES FOR CELL BACKGROUND to guarantee visibility
                                                let cellStyle: React.CSSProperties = {
                                                    transition: 'background-color 0.2s',
                                                    padding: 0
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#d1fae5'; // emerald-100
                                                    cellStyle.color = '#065f46'; // emerald-800
                                                    cellStyle.fontWeight = 'bold';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1e40af'; // blue-800
                                                    cellStyle.fontWeight = 'bold';
                                                }

                                                return (
                                                    <td key={month.id} className="border-r border-gray-100 last:border-r-0" style={cellStyle}>
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className="w-full h-full text-center py-2.5 outline-none"
                                                            style={{
                                                                width: '100%', 
                                                                height: '100%', 
                                                                border: 'none', 
                                                                background: 'transparent',
                                                                color: 'inherit',
                                                                fontWeight: 'inherit',
                                                                textAlign: 'center'
                                                            }}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/30">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="w-full bg-transparent text-xs text-right focus:outline-none cursor-pointer"
                                                        style={{color: visitColor, fontWeight: 'bold'}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center bg-gray-50/30">
                                                <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:bg-blue-100 p-1.5 rounded transition-colors" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-gray-400 hover:text-red-600 hover:bg-red-50 p-1.5 rounded transition-colors" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                    style={{border: 'none', background: 'transparent'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr style={{backgroundColor: '#e0e7ff', borderBottom: '2px solid #c7d2fe'}}>
                                    <th className="py-3 px-4 font-bold text-indigo-900 sticky left-0 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] border-r border-indigo-200 uppercase text-xs tracking-wider" style={{backgroundColor: '#e0e7ff'}}>
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-bold text-indigo-800 w-16 border-r border-indigo-200 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-bold text-indigo-900 border-l border-indigo-200 w-36 uppercase text-xs tracking-wider">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = '#16a34a'; // green-600
                                        else if (daysSince < 180) visitColor = '#ea580c'; // orange-600
                                        else visitColor = '#dc2626'; // red-600
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-indigo-50/30 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-indigo-50/30 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-semibold text-gray-800 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // CHIP-STYLE INPUT
                                                let cellStyle: React.CSSProperties = {
                                                    textAlign: 'center',
                                                    width: 'calc(100% - 8px)',
                                                    margin: '0 4px',
                                                    height: '28px',
                                                    borderRadius: '6px',
                                                    border: 'none',
                                                    outline: 'none',
                                                    backgroundColor: 'transparent',
                                                    color: '#4b5563', // gray-600 default
                                                    fontWeight: 'normal',
                                                    transition: 'all 0.2s ease',
                                                    cursor: 'pointer'
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#dcfce7'; // green-100
                                                    cellStyle.color = '#15803d'; // green-700
                                                    cellStyle.fontWeight = 'bold';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1d4ed8'; // blue-700
                                                    cellStyle.fontWeight = 'bold';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } 

                                                // Hover style logic is handled via CSS classes usually, but for inline react style we can rely on focus.
                                                // We can add a class for hover effects if needed, but the clean colored chips look good.

                                                return (
                                                    <td key={month.id} className="p-1 border-r border-gray-100 last:border-r-0">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className="hover:bg-gray-100 focus:bg-white focus:ring-2 focus:ring-indigo-300"
                                                            style={cellStyle}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/20">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="w-full bg-transparent text-xs text-center focus:outline-none cursor-pointer font-bold rounded px-1"
                                                        style={{color: visitColor}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center">
                                                <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:text-blue-800 bg-blue-50 hover:bg-blue-100 p-1.5 rounded-full transition-colors shadow-sm" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-500 hover:text-red-700 bg-red-50 hover:bg-red-100 p-1.5 rounded-full transition-colors shadow-sm" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-2 py-6 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS --- */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                <div className="flex-1 w-full md:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex items-center gap-3">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-transparent text-xl font-bold text-gray-800 pr-8 cursor-pointer focus:outline-none hover:text-blue-700 transition-colors"
                                    style={{border: 'none', background: 'transparent'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 group-hover:text-blue-500 pointer-events-none text-sm transition-colors"></i>
                            </div>
                            <button onClick={() => setIsCreatingGroup(true)} className="w-8 h-8 rounded-md hover:bg-gray-100 text-gray-600 flex items-center justify-center transition-colors" title="Nuevo Grupo">
                                <i className="fas fa-plus"></i>
                            </button>
                            {groups.length > 0 && (
                                <button onClick={handleDeleteGroup} className="w-8 h-8 rounded-md hover:bg-red-50 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors" title="Eliminar Grupo">
                                    <i className="fas fa-trash-alt text-sm"></i>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="border border-gray-300 rounded-md px-3 py-1.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />
                            <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-3 py-1.5 rounded-md text-sm hover:bg-blue-700">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md text-sm hover:bg-gray-300">Cancelar</button>
                        </div>
                    )}
                    <p className="text-gray-500 text-sm mt-1">
                        {members.length} Publicadores
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full md:w-auto justify-end">
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">
                        <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Reporte:</span>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-semibold text-gray-700 focus:outline-none cursor-pointer"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="text-gray-500 hover:text-blue-600 ml-1 transition-colors" title="Descargar reporte">
                            <i className="fas fa-download"></i>
                        </button>
                    </div>

                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-800 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="text-gray-400 hover:text-blue-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SEARCH --- */}
            {selectedGroupId && (
                <div className="mb-6 relative" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="flex gap-2">
                        <div className="relative flex-grow max-w-md">
                            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                                placeholder="Agregar publicador..."
                                className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none shadow-sm text-sm"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto z-50">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-4 py-2.5 hover:bg-gray-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0">
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus text-gray-400 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-4 py-2.5 bg-blue-50 hover:bg-blue-100 cursor-pointer flex items-center gap-3 text-blue-700 font-medium">
                                        <i className="fas fa-pen text-xs"></i>
                                        Crear "{addSearchTerm}"
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-sm transition-colors text-sm">
                            Agregar
                        </button>
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-lg shadow-lg text-white font-medium flex items-center gap-3 z-50 animate-fade-in-up`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- ANNUAL GRID TABLE --- */}
            {loading ? (
                <div className="text-center py-20 text-gray-400">
                    <i className="fas fa-spinner fa-spin fa-2x mb-3"></i>
                    <p>Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden flex flex-col">

                    {/* Responsive Scroll Wrapper */}
                    <div className="overflow-x-auto w-full">
                        <table className="w-full text-sm text-left border-collapse" style={{minWidth: '1000px'}}>
                            <thead>
                                <tr style={{backgroundColor: '#e0e7ff', borderBottom: '2px solid #c7d2fe'}}>
                                    <th className="py-3 px-4 font-bold text-indigo-900 sticky left-0 z-10 w-56 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] border-r border-indigo-200 uppercase text-xs tracking-wider" style={{backgroundColor: '#e0e7ff'}}>
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-3 px-2 text-center font-bold text-indigo-800 w-16 border-r border-indigo-200 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-3 px-4 text-center font-bold text-indigo-900 border-l border-indigo-200 w-36 uppercase text-xs tracking-wider">
                                        Ult. Visita
                                    </th>
                                    <th className="py-3 px-4 text-center w-16"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) visitColor = '#16a34a'; // green-600
                                        else if (daysSince < 180) visitColor = '#ea580c'; // orange-600
                                        else visitColor = '#dc2626'; // red-600
                                    }

                                    return (
                                        <tr key={m.id} className="hover:bg-indigo-50/30 transition-colors group">
                                            {/* Name (Sticky) */}
                                            <td className="py-2.5 px-4 sticky left-0 bg-white group-hover:bg-indigo-50/30 z-10 border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-semibold text-gray-800 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // CHIP-STYLE INPUT
                                                let cellStyle: React.CSSProperties = {
                                                    textAlign: 'center',
                                                    width: 'calc(100% - 8px)',
                                                    margin: '0 4px',
                                                    height: '28px',
                                                    borderRadius: '6px',
                                                    border: 'none',
                                                    outline: 'none',
                                                    backgroundColor: 'transparent',
                                                    color: '#4b5563', // gray-600 default
                                                    fontWeight: 'normal',
                                                    transition: 'all 0.2s ease',
                                                    cursor: 'pointer'
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#dcfce7'; // green-100
                                                    cellStyle.color = '#15803d'; // green-700
                                                    cellStyle.fontWeight = 'bold';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1d4ed8'; // blue-700
                                                    cellStyle.fontWeight = 'bold';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } 

                                                // Hover style logic is handled via CSS classes usually, but for inline react style we can rely on focus.
                                                // We can add a class for hover effects if needed, but the clean colored chips look good.

                                                return (
                                                    <td key={month.id} className="p-1 border-r border-gray-100 last:border-r-0">
                                                        <input 
                                                            type="text" 
                                                            value={val}
                                                            onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                            className="hover:bg-gray-100 focus:bg-white focus:ring-2 focus:ring-indigo-300"
                                                            style={cellStyle}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-2 border-l border-gray-200 bg-gray-50/20">
                                                <div className="relative">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="w-full bg-transparent text-xs text-center focus:outline-none cursor-pointer font-bold rounded px-1"
                                                        style={{color: visitColor}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-2 px-2 text-center">
                                                <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-blue-600 hover:text-blue-800 bg-blue-50 hover:bg-blue-100 p-1.5 rounded-full transition-colors shadow-sm" title="Guardar Fila">
                                                        <i className="fas fa-save"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-500 hover:text-red-700 bg-red-50 hover:bg-red-100 p-1.5 rounded-full transition-colors shadow-sm" title="Eliminar">
                                                        <i className="fas fa-trash-alt"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="p-16 text-center bg-white">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                                <i className="fas fa-users text-gray-300 text-2xl"></i>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900">Grupo sin miembros</h3>
                            <p className="text-gray-500 mt-1">Utiliza el buscador superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-4 py-8 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS CARD --- */}
            <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 mb-8 bg-white p-6 rounded-3xl shadow-lg border border-gray-100 transition-shadow hover:shadow-xl">
                <div className="flex-1 w-full xl:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-indigo-50/50 hover:bg-indigo-50 text-2xl font-bold text-gray-800 pl-4 pr-10 py-2 rounded-xl cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-200 transition-all"
                                    style={{border: 'none'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-indigo-400 pointer-events-none text-sm"></i>
                            </div>

                            <div className="flex items-center gap-2 mt-2 sm:mt-0">
                                <button onClick={() => setIsCreatingGroup(true)} className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Nuevo Grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} className="w-10 h-10 rounded-full bg-red-50 text-red-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Eliminar Grupo">
                                        <i className="fas fa-trash-alt"></i>
                                    </button>
                                )}
                            </div>
                            <span className="text-gray-400 text-sm font-medium px-2 py-1 bg-gray-50 rounded-lg border border-gray-100">
                                {members.length} Publicadores
                            </span>
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center bg-gray-50 p-2 rounded-xl border border-gray-200">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="bg-white border-none rounded-lg px-4 py-2 text-base focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm" />
                            <button onClick={handleCreateGroup} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 shadow-md">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-white text-gray-600 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-100 border border-gray-200">Cancelar</button>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto justify-end">
                    {/* Year Selector Pill */}
                    <div className="flex items-center bg-white p-1 rounded-full border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-700 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>

                    {/* Report Selector Pill */}
                    <div className="flex items-center gap-3 bg-gray-50 pl-4 pr-2 py-1.5 rounded-full border border-gray-200">
                        <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Reporte</span>
                        <div className="h-4 w-px bg-gray-300"></div>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-bold text-gray-700 focus:outline-none cursor-pointer hover:text-indigo-600"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="w-8 h-8 flex items-center justify-center rounded-full bg-white text-indigo-600 shadow-sm hover:shadow-md hover:bg-indigo-600 hover:text-white transition-all ml-1" title="Descargar reporte">
                            <i className="fas fa-download text-xs"></i>
                        </button>
                    </div>
                </div>
            </div>

            {/* --- SEARCH BAR --- */}
            {selectedGroupId && (
                <div className="mb-8 relative max-w-2xl mx-auto" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                            <i className="fas fa-search text-gray-400 group-focus-within:text-indigo-500 transition-colors"></i>
                        </div>
                        <input 
                            type="text" 
                            value={addSearchTerm}
                            onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                            onFocus={() => setShowSuggestions(true)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                            placeholder="Buscar y agregar publicador..."
                            className="w-full pl-11 pr-24 py-3.5 bg-white border border-gray-200 rounded-full focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none shadow-sm text-base transition-all"
                        />
                        <div className="absolute inset-y-1.5 right-1.5">
                            <button 
                                onClick={() => handleAddMember(addSearchTerm)} 
                                disabled={!addSearchTerm} 
                                className="h-full px-5 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-md transition-all text-sm flex items-center gap-2"
                            >
                                <i className="fas fa-plus"></i> Agregar
                            </button>
                        </div>

                        {/* Suggestions Dropdown */}
                        {showSuggestions && addSearchTerm && (
                            <div className="absolute top-full left-4 right-4 mt-2 bg-white border border-gray-100 rounded-2xl shadow-xl max-h-60 overflow-y-auto z-50 overflow-hidden">
                                {filteredSuggestions.map(p => (
                                    <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-indigo-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0 transition-colors">
                                        <span className="text-gray-700 font-medium">{p.nombre}</span>
                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center">
                                            <i className="fas fa-plus text-xs"></i>
                                        </div>
                                    </div>
                                ))}
                                <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-5 py-3 bg-gray-50 hover:bg-gray-100 cursor-pointer flex items-center gap-3 text-indigo-600 font-medium border-t border-gray-100">
                                    <i className="fas fa-pen text-xs"></i>
                                    Crear nuevo "{addSearchTerm}"
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-8 right-8 px-6 py-4 rounded-2xl shadow-2xl text-white font-bold flex items-center gap-4 z-50 animate-fade-in-up transform hover:scale-105 transition-transform`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'} text-xl`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- MAIN DATA CARD --- */}
            {loading ? (
                <div className="text-center py-24 text-gray-400 bg-white rounded-3xl shadow-sm border border-gray-100">
                    <i className="fas fa-circle-notch fa-spin fa-3x mb-4 text-indigo-200"></i>
                    <p className="text-lg font-medium text-gray-500">Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-100 rounded-[2rem] shadow-xl overflow-hidden flex flex-col relative">

                    {/* Scroll Wrapper */}
                    <div className="overflow-x-auto w-full custom-scrollbar">
                        <table className="w-full text-left border-collapse" style={{minWidth: '1100px'}}>
                            <thead>
                                <tr className="border-b border-gray-100">
                                    <th className="py-5 px-6 font-bold text-gray-700 sticky left-0 z-20 w-64 uppercase text-xs tracking-wider bg-gray-50/95 backdrop-blur-sm border-r border-gray-100 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)]">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-4 px-2 text-center font-bold text-gray-400 w-20 border-r border-gray-50 last:border-r-0 uppercase text-xs tracking-wider bg-white">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-4 px-4 text-center font-bold text-gray-700 border-l border-gray-100 w-40 uppercase text-xs tracking-wider bg-gray-50">
                                        Ult. Visita
                                    </th>
                                    <th className="py-4 px-4 text-center w-20 bg-white"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    let visitBg = 'transparent';
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) { visitColor = '#059669'; visitBg = '#ecfdf5'; } // emerald-600 / 50
                                        else if (daysSince < 180) { visitColor = '#d97706'; visitBg = '#fffbeb'; } // amber-600 / 50
                                        else { visitColor = '#dc2626'; visitBg = '#fef2f2'; } // red-600 / 50
                                    }

                                    return (
                                        <tr key={m.id} className="group hover:bg-gray-50/50 transition-colors">
                                            {/* Name (Sticky) */}
                                            <td className="py-4 px-6 sticky left-0 bg-white group-hover:bg-gray-50/50 z-10 border-r border-gray-100 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 rounded-full bg-gradient-to-br from-indigo-100 to-purple-50 text-indigo-600 flex items-center justify-center font-bold text-xs shadow-sm border border-indigo-50">
                                                        {pName.charAt(0)}
                                                    </div>
                                                    <span className="font-semibold text-gray-700 truncate max-w-[160px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs - PILL STYLE */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // PILL-STYLE INPUT STYLING
                                                let cellStyle: React.CSSProperties = {
                                                    textAlign: 'center',
                                                    width: '42px',
                                                    height: '28px',
                                                    margin: '0 auto',
                                                    borderRadius: '9999px', // Fully rounded pill
                                                    border: '1px solid transparent',
                                                    outline: 'none',
                                                    backgroundColor: 'transparent',
                                                    color: '#6b7280', // gray-500
                                                    fontWeight: '500',
                                                    fontSize: '0.85rem',
                                                    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                                                    cursor: 'text'
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#dcfce7'; // green-100
                                                    cellStyle.color = '#166534'; // green-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1e40af'; // blue-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (val !== '') {
                                                    // Any other text
                                                    cellStyle.backgroundColor = '#f3f4f6';
                                                    cellStyle.color = '#374151';
                                                }

                                                // Focus style handled via className if possible, or inline
                                                // We add a focus ring simulation via box-shadow in JS is tricky, 
                                                // so we'll rely on a surrounding div or just the input style.

                                                return (
                                                    <td key={month.id} className="p-1 border-r border-gray-50 last:border-r-0 align-middle">
                                                        <div className="flex items-center justify-center h-full w-full">
                                                            <input 
                                                                type="text" 
                                                                value={val}
                                                                onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                                className="focus:bg-white focus:ring-2 focus:ring-indigo-200 focus:border-indigo-300 hover:bg-gray-50"
                                                                style={cellStyle}
                                                                placeholder="-"
                                                            />
                                                        </div>
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-3 border-l border-gray-100 bg-gray-50/30">
                                                <div className="relative flex justify-center">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="bg-transparent text-xs text-center focus:outline-none cursor-pointer font-bold rounded-lg px-2 py-1 transition-all hover:shadow-sm"
                                                        style={{color: visitColor, backgroundColor: visitBg}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-3 px-3 text-center">
                                                <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200 transform translate-x-2 group-hover:translate-x-0">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-indigo-600 hover:text-indigo-800 bg-indigo-50 hover:bg-indigo-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Guardar Fila">
                                                        <i className="fas fa-save text-xs"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-400 hover:text-red-600 bg-red-50 hover:bg-red-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Eliminar">
                                                        <i className="fas fa-trash-alt text-xs"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="py-24 text-center bg-white">
                            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6 border border-gray-100 shadow-inner">
                                <i className="fas fa-users text-gray-300 text-3xl"></i>
                            </div>
                            <h3 className="text-xl font-bold text-gray-800 mb-2">Este grupo está vacío</h3>
                            <p className="text-gray-500 max-w-xs mx-auto">Utiliza la barra de búsqueda superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-4 py-8 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS CARD --- */}
            <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 mb-8 bg-white p-6 rounded-3xl shadow-lg border border-gray-200 transition-shadow hover:shadow-xl">
                <div className="flex-1 w-full xl:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-indigo-50/50 hover:bg-indigo-50 text-2xl font-bold text-gray-800 pl-4 pr-10 py-2 rounded-xl cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-200 transition-all"
                                    style={{border: 'none'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-indigo-400 pointer-events-none text-sm"></i>
                            </div>

                            <div className="flex items-center gap-2 mt-2 sm:mt-0">
                                <button onClick={() => setIsCreatingGroup(true)} className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Nuevo Grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} className="w-10 h-10 rounded-full bg-red-50 text-red-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Eliminar Grupo">
                                        <i className="fas fa-trash-alt"></i>
                                    </button>
                                )}
                            </div>
                            <span className="text-gray-400 text-sm font-medium px-2 py-1 bg-gray-50 rounded-lg border border-gray-100">
                                {members.length} Publicadores
                            </span>
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center bg-gray-50 p-2 rounded-xl border border-gray-200">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="bg-white border-none rounded-lg px-4 py-2 text-base focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm" />
                            <button onClick={handleCreateGroup} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 shadow-md">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-white text-gray-600 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-100 border border-gray-200">Cancelar</button>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto justify-end">
                    {/* Year Selector Pill */}
                    <div className="flex items-center bg-white p-1 rounded-full border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-700 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>

                    {/* Report Selector Pill */}
                    <div className="flex items-center gap-3 bg-gray-50 pl-4 pr-2 py-1.5 rounded-full border border-gray-200">
                        <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Reporte</span>
                        <div className="h-4 w-px bg-gray-300"></div>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-bold text-gray-700 focus:outline-none cursor-pointer hover:text-indigo-600"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="w-8 h-8 flex items-center justify-center rounded-full bg-white text-indigo-600 shadow-sm hover:shadow-md hover:bg-indigo-600 hover:text-white transition-all ml-1" title="Descargar reporte">
                            <i className="fas fa-download text-xs"></i>
                        </button>
                    </div>
                </div>
            </div>

            {/* --- SEARCH BAR --- */}
            {selectedGroupId && (
                <div className="mb-8 relative max-w-2xl mx-auto" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                            <i className="fas fa-search text-gray-400 group-focus-within:text-indigo-500 transition-colors"></i>
                        </div>
                        <input 
                            type="text" 
                            value={addSearchTerm}
                            onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                            onFocus={() => setShowSuggestions(true)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                            placeholder="Buscar y agregar publicador..."
                            className="w-full pl-11 pr-24 py-3.5 bg-white border border-gray-200 rounded-full focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none shadow-sm text-base transition-all"
                        />
                        <div className="absolute inset-y-1.5 right-1.5">
                            <button 
                                onClick={() => handleAddMember(addSearchTerm)} 
                                disabled={!addSearchTerm} 
                                className="h-full px-5 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-md transition-all text-sm flex items-center gap-2"
                            >
                                <i className="fas fa-plus"></i> Agregar
                            </button>
                        </div>

                        {/* Suggestions Dropdown */}
                        {showSuggestions && addSearchTerm && (
                            <div className="absolute top-full left-4 right-4 mt-2 bg-white border border-gray-100 rounded-2xl shadow-xl max-h-60 overflow-y-auto z-50 overflow-hidden">
                                {filteredSuggestions.map(p => (
                                    <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-indigo-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0 transition-colors">
                                        <span className="text-gray-700 font-medium">{p.nombre}</span>
                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center">
                                            <i className="fas fa-plus text-xs"></i>
                                        </div>
                                    </div>
                                ))}
                                <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-5 py-3 bg-gray-50 hover:bg-gray-100 cursor-pointer flex items-center gap-3 text-indigo-600 font-medium border-t border-gray-100">
                                    <i className="fas fa-pen text-xs"></i>
                                    Crear nuevo "{addSearchTerm}"
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-8 right-8 px-6 py-4 rounded-2xl shadow-2xl text-white font-bold flex items-center gap-4 z-50 animate-fade-in-up transform hover:scale-105 transition-transform`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'} text-xl`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- MAIN DATA CARD --- */}
            {loading ? (
                <div className="text-center py-24 text-gray-400 bg-white rounded-3xl shadow-sm border border-gray-100">
                    <i className="fas fa-circle-notch fa-spin fa-3x mb-4 text-indigo-200"></i>
                    <p className="text-lg font-medium text-gray-500">Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-[2rem] shadow-xl overflow-hidden flex flex-col relative">

                    {/* Scroll Wrapper */}
                    <div className="overflow-x-auto w-full custom-scrollbar">
                        <table className="w-full text-left border-collapse" style={{minWidth: '1100px'}}>
                            <thead>
                                <tr className="border-b border-gray-200 bg-gray-100">
                                    <th className="py-5 px-6 font-bold text-gray-700 sticky left-0 z-20 w-64 uppercase text-xs tracking-wider bg-gray-100 border-r border-gray-300 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)]">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-4 px-2 text-center font-bold text-gray-600 w-20 border-r border-gray-300 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-4 px-4 text-center font-bold text-gray-700 border-l border-gray-300 w-40 uppercase text-xs tracking-wider bg-gray-100">
                                        Ult. Visita
                                    </th>
                                    <th className="py-4 px-4 text-center w-20 border-l border-gray-300"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    let visitBg = 'transparent';
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) { visitColor = '#059669'; visitBg = '#ecfdf5'; } // emerald-600 / 50
                                        else if (daysSince < 180) { visitColor = '#d97706'; visitBg = '#fffbeb'; } // amber-600 / 50
                                        else { visitColor = '#dc2626'; visitBg = '#fef2f2'; } // red-600 / 50
                                    }

                                    return (
                                        <tr key={m.id} className="group hover:bg-gray-50/30 transition-colors">
                                            {/* Name (Sticky) */}
                                            <td className="py-3 px-6 sticky left-0 bg-white group-hover:bg-gray-50/30 z-10 border-r border-gray-300 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-semibold text-gray-700 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs - PILL STYLE */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // PILL-STYLE INPUT STYLING
                                                let cellStyle: React.CSSProperties = {
                                                    textAlign: 'center',
                                                    width: '42px',
                                                    height: '28px',
                                                    margin: '0 auto',
                                                    borderRadius: '9999px', // Fully rounded pill
                                                    border: '1px solid transparent',
                                                    outline: 'none',
                                                    backgroundColor: 'transparent',
                                                    color: '#6b7280', // gray-500
                                                    fontWeight: '500',
                                                    fontSize: '0.85rem',
                                                    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                                                    cursor: 'text'
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#dcfce7'; // green-100
                                                    cellStyle.color = '#166534'; // green-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1e40af'; // blue-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (val !== '') {
                                                    // Any other text
                                                    cellStyle.backgroundColor = '#f3f4f6';
                                                    cellStyle.color = '#374151';
                                                }

                                                return (
                                                    <td key={month.id} className="p-1 border-r border-gray-300 last:border-r-0 align-middle">
                                                        <div className="flex items-center justify-center h-full w-full">
                                                            <input 
                                                                type="text" 
                                                                value={val}
                                                                onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                                className="focus:bg-white focus:ring-2 focus:ring-indigo-200 focus:border-indigo-300 hover:bg-gray-100"
                                                                style={cellStyle}
                                                                placeholder="-"
                                                            />
                                                        </div>
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-3 border-l border-gray-300 bg-gray-50/20">
                                                <div className="relative flex justify-center">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="bg-transparent text-xs text-center focus:outline-none cursor-pointer font-bold rounded-lg px-2 py-1 transition-all hover:shadow-sm"
                                                        style={{color: visitColor, backgroundColor: visitBg}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-3 px-3 text-center border-l border-gray-300">
                                                <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200 transform translate-x-2 group-hover:translate-x-0">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-indigo-600 hover:text-indigo-800 bg-indigo-50 hover:bg-indigo-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Guardar Fila">
                                                        <i className="fas fa-save text-xs"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-400 hover:text-red-600 bg-red-50 hover:bg-red-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Eliminar">
                                                        <i className="fas fa-trash-alt text-xs"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="py-24 text-center bg-white">
                            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6 border border-gray-100 shadow-inner">
                                <i className="fas fa-users text-gray-300 text-3xl"></i>
                            </div>
                            <h3 className="text-xl font-bold text-gray-800 mb-2">Este grupo está vacío</h3>
                            <p className="text-gray-500 max-w-xs mx-auto">Utiliza la barra de búsqueda superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

// Data structure: { "PublisherName": { "01": "10", "02": "si", ... } }
type AnnualReportsMap = Record<string, Record<string, string>>; 
type VisitsMap = Record<string, string>;

const MONTHS = [
    { id: '01', name: 'Ene' }, { id: '02', name: 'Feb' }, { id: '03', name: 'Mar' },
    { id: '04', name: 'Abr' }, { id: '05', name: 'May' }, { id: '06', name: 'Jun' },
    { id: '07', name: 'Jul' }, { id: '08', name: 'Ago' }, { id: '09', name: 'Sep' },
    { id: '10', name: 'Oct' }, { id: '11', name: 'Nov' }, { id: '12', name: 'Dic' }
];

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
    const [reportData, setReportData] = useState<AnnualReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({}); 

    // Report Generation State
    const [selectedReportMonth, setSelectedReportMonth] = useState<string>(String(new Date().getMonth() + 1).padStart(2, '0'));

    // Actions State
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) console.error("Error fetching groups:", error);
        else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to preserve selection or default
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Trigger fetch on group change
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load ANNUAL Reports when Members or Year Change
    useEffect(() => {
        if (members.length === 0) return;

        const fetchAnnualData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            // Fetch reports for the WHOLE selected year
            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, mes, horas')
                .in('publicador_nombre', memberNames)
                .ilike('mes', `${currentYear}-%`); 

            const newReportData: AnnualReportsMap = {};

            // Initialize empty structure for members
            memberNames.forEach(name => {
                newReportData[name] = {};
            });

            if (reportsData) {
                reportsData.forEach((r: any) => {
                    const monthPart = r.mes.split('-')[1]; // Get '01', '02' from '2024-01'
                    if (newReportData[r.publicador_nombre]) {
                        newReportData[r.publicador_nombre][monthPart] = String(r.horas);
                    }
                });
            }
            setReportData(newReportData);

            // Fetch Last Visits
            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchAnnualData();
    }, [currentYear, members]);

    // --- Logic ---

    const handleCellChange = (publisherName: string, monthId: string, value: string) => {
        setReportData(prev => ({
            ...prev,
            [publisherName]: {
                ...(prev[publisherName] || {}),
                [monthId]: value
            }
        }));
    };

    const handleVisitChange = (publisherName: string, date: string) => {
        setVisits(prev => ({ ...prev, [publisherName]: date }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // 1. Upsert Reports for this user for the whole year
            const userReports = reportData[publisherName] || {};
            const reportsToUpsert = Object.entries(userReports).map(([monthId, horas]) => ({
                publicador_nombre: publisherName,
                mes: `${currentYear}-${monthId}`,
                horas: horas
            })).filter(r => r.horas !== ''); 

            if (reportsToUpsert.length > 0) {
                const { error } = await supabase.from('informes_ministerio').upsert(reportsToUpsert, { onConflict: 'publicador_nombre, mes' });
                if (error) throw error;
            }

            // 2. Upsert Visit
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Actions
    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();
        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();
        if (error) {
             setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Ya existe en el grupo', type: 'error' }); return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (!error) {
            setStatusMessage({ text: 'Agregado', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name}?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId || !window.confirm("¿Eliminar grupo completo?")) return;
        await supabase.from('grupos').delete().eq('id', selectedGroupId);
        setGroups(prev => prev.filter(g => g.id !== selectedGroupId));
        setSelectedGroupId(null);
        setMembers([]);
    };

    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre))
        .slice(0, 6);

    const handleDownloadReport = () => {
        const monthName = MONTHS.find(m => m.id === selectedReportMonth)?.name;
        alert(`Generando reporte para: ${monthName} ${currentYear}\n(Funcionalidad de impresión S-21)`);
    };

    return (
        <div className="container mx-auto px-4 py-8 group-container" style={{maxWidth: '100%', overflowX: 'hidden'}}>

            {/* --- TOP CONTROLS CARD --- */}
            <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 mb-8 bg-white p-6 rounded-3xl shadow-lg border border-gray-200 transition-shadow hover:shadow-xl">
                <div className="flex-1 w-full xl:w-auto">
                    {!isCreatingGroup ? (
                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                            <div className="relative group">
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="appearance-none bg-indigo-50/50 hover:bg-indigo-50 text-2xl font-bold text-gray-800 pl-4 pr-10 py-2 rounded-xl cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-200 transition-all"
                                    style={{border: 'none'}}
                                >
                                    {groups.length === 0 && <option value="">Crear grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-indigo-400 pointer-events-none text-sm"></i>
                            </div>

                            <div className="flex items-center gap-2 mt-2 sm:mt-0">
                                <button onClick={() => setIsCreatingGroup(true)} className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Nuevo Grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} className="w-10 h-10 rounded-full bg-red-50 text-red-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-all shadow-sm" title="Eliminar Grupo">
                                        <i className="fas fa-trash-alt"></i>
                                    </button>
                                )}
                            </div>
                            <span className="text-gray-400 text-sm font-medium px-2 py-1 bg-gray-50 rounded-lg border border-gray-100">
                                {members.length} Publicadores
                            </span>
                        </div>
                    ) : (
                        <div className="flex gap-2 items-center bg-gray-50 p-2 rounded-xl border border-gray-200">
                            <input autoFocus type="text" placeholder="Nombre Grupo" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="bg-white border-none rounded-lg px-4 py-2 text-base focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm" />
                            <button onClick={handleCreateGroup} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 shadow-md">Guardar</button>
                            <button onClick={() => setIsCreatingGroup(false)} className="bg-white text-gray-600 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-100 border border-gray-200">Cancelar</button>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto justify-end">
                    {/* Year Selector Pill */}
                    <div className="flex items-center bg-white p-1 rounded-full border border-gray-200 shadow-sm">
                        <button onClick={() => setCurrentYear(y => y - 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-left"></i></button>
                        <span className="text-lg font-bold text-gray-700 w-16 text-center tabular-nums">{currentYear}</span>
                        <button onClick={() => setCurrentYear(y => y + 1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-indigo-600 transition-colors"><i className="fas fa-chevron-right"></i></button>
                    </div>

                    {/* Report Selector Pill */}
                    <div className="flex items-center gap-3 bg-gray-50 pl-4 pr-2 py-1.5 rounded-full border border-gray-200">
                        <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Reporte</span>
                        <div className="h-4 w-px bg-gray-300"></div>
                        <select 
                            value={selectedReportMonth}
                            onChange={(e) => setSelectedReportMonth(e.target.value)}
                            className="bg-transparent text-sm font-bold text-gray-700 focus:outline-none cursor-pointer hover:text-indigo-600"
                            style={{border:'none', background:'transparent'}}
                        >
                            {MONTHS.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </select>
                        <button onClick={handleDownloadReport} className="w-8 h-8 flex items-center justify-center rounded-full bg-white text-indigo-600 shadow-sm hover:shadow-md hover:bg-indigo-600 hover:text-white transition-all ml-1" title="Descargar reporte">
                            <i className="fas fa-download text-xs"></i>
                        </button>
                    </div>
                </div>
            </div>

            {/* --- SEARCH BAR --- */}
            {selectedGroupId && (
                <div className="mb-8 relative max-w-2xl mx-auto" ref={suggestionsRef} style={{zIndex: 20}}>
                    <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                            <i className="fas fa-search text-gray-400 group-focus-within:text-indigo-500 transition-colors"></i>
                        </div>
                        <input 
                            type="text" 
                            value={addSearchTerm}
                            onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                            onFocus={() => setShowSuggestions(true)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAddMember(addSearchTerm)}
                            placeholder="Buscar y agregar publicador..."
                            className="w-full pl-11 pr-24 py-3.5 bg-white border border-gray-200 rounded-full focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none shadow-sm text-base transition-all"
                        />
                        <div className="absolute inset-y-1.5 right-1.5">
                            <button 
                                onClick={() => handleAddMember(addSearchTerm)} 
                                disabled={!addSearchTerm} 
                                className="h-full px-5 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-md transition-all text-sm flex items-center gap-2"
                            >
                                <i className="fas fa-plus"></i> Agregar
                            </button>
                        </div>

                        {/* Suggestions Dropdown */}
                        {showSuggestions && addSearchTerm && (
                            <div className="absolute top-full left-4 right-4 mt-2 bg-white border border-gray-100 rounded-2xl shadow-xl max-h-60 overflow-y-auto z-50 overflow-hidden">
                                {filteredSuggestions.map(p => (
                                    <div key={p.id} onClick={() => { handleAddMember(p.nombre); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-indigo-50 cursor-pointer flex items-center justify-between border-b border-gray-50 last:border-0 transition-colors">
                                        <span className="text-gray-700 font-medium">{p.nombre}</span>
                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center">
                                            <i className="fas fa-plus text-xs"></i>
                                        </div>
                                    </div>
                                ))}
                                <div onClick={() => { handleAddMember(addSearchTerm); setShowSuggestions(false); }} className="px-5 py-3 bg-gray-50 hover:bg-gray-100 cursor-pointer flex items-center gap-3 text-indigo-600 font-medium border-t border-gray-100">
                                    <i className="fas fa-pen text-xs"></i>
                                    Crear nuevo "{addSearchTerm}"
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* --- STATUS TOAST --- */}
            {statusMessage && (
                <div className={`fixed bottom-8 right-8 px-6 py-4 rounded-2xl shadow-2xl text-white font-bold flex items-center gap-4 z-50 animate-fade-in-up transform hover:scale-105 transition-transform`} style={{backgroundColor: statusMessage.type === 'success' ? '#10b981' : '#ef4444'}}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'} text-xl`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* --- MAIN DATA CARD --- */}
            {loading ? (
                <div className="text-center py-24 text-gray-400 bg-white rounded-3xl shadow-sm border border-gray-100">
                    <i className="fas fa-circle-notch fa-spin fa-3x mb-4 text-indigo-200"></i>
                    <p className="text-lg font-medium text-gray-500">Cargando datos del año {currentYear}...</p>
                </div>
            ) : (
                <div className="bg-white border border-gray-200 rounded-[2rem] shadow-xl overflow-hidden flex flex-col relative">

                    {/* Scroll Wrapper */}
                    <div className="overflow-x-auto w-full custom-scrollbar">
                        <table className="w-full text-left border-collapse" style={{minWidth: '1100px'}}>
                            <thead>
                                <tr className="border-b border-gray-300 bg-gray-100">
                                    <th className="py-5 px-6 font-bold text-gray-700 sticky left-0 z-20 w-64 uppercase text-xs tracking-wider bg-gray-100 border-r border-gray-300 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)] border-t border-gray-300">
                                        Publicador
                                    </th>
                                    {MONTHS.map(m => (
                                        <th key={m.id} className="py-4 px-2 text-center font-bold text-gray-600 w-20 border-r border-t border-gray-300 last:border-r-0 uppercase text-xs tracking-wider">
                                            {m.name}
                                        </th>
                                    ))}
                                    <th className="py-4 px-4 text-center font-bold text-gray-700 border-l border-r border-t border-gray-300 w-40 uppercase text-xs tracking-wider bg-gray-100">
                                        Ult. Visita
                                    </th>
                                    <th className="py-4 px-4 text-center w-20 border-l border-t border-gray-300 bg-white"></th>
                                </tr>
                            </thead>
                            <tbody className="bg-white">
                                {members.map((m) => {
                                    const pName = m.publicador_nombre;
                                    const visitDate = visits[pName] || '';

                                    // Visual cue for Visit
                                    let visitColor = '#9ca3af'; // gray-400
                                    let visitBg = 'transparent';
                                    if (visitDate) {
                                        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                        if (daysSince < 90) { visitColor = '#059669'; visitBg = '#ecfdf5'; } // emerald-600 / 50
                                        else if (daysSince < 180) { visitColor = '#d97706'; visitBg = '#fffbeb'; } // amber-600 / 50
                                        else { visitColor = '#dc2626'; visitBg = '#fef2f2'; } // red-600 / 50
                                    }

                                    return (
                                        <tr key={m.id} className="group hover:bg-gray-50/30 transition-colors">
                                            {/* Name (Sticky) */}
                                            <td className="py-3 px-6 sticky left-0 bg-white group-hover:bg-gray-50/30 z-10 border-r border-b border-gray-300 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)]">
                                                <div className="flex items-center">
                                                    <span className="font-semibold text-gray-700 truncate max-w-[180px]" title={pName}>{pName}</span>
                                                </div>
                                            </td>

                                            {/* 12 Months Grid Inputs - PILL STYLE */}
                                            {MONTHS.map(month => {
                                                const val = reportData[pName]?.[month.id] || '';
                                                const lowerVal = val.toLowerCase().trim();
                                                const isSi = lowerVal === 'si';
                                                const isNum = !isSi && val.trim() !== '' && !isNaN(Number(val));

                                                // PILL-STYLE INPUT STYLING
                                                let cellStyle: React.CSSProperties = {
                                                    textAlign: 'center',
                                                    width: '42px',
                                                    height: '28px',
                                                    margin: '0 auto',
                                                    borderRadius: '9999px', // Fully rounded pill
                                                    border: '1px solid transparent',
                                                    outline: 'none',
                                                    backgroundColor: 'transparent',
                                                    color: '#6b7280', // gray-500
                                                    fontWeight: '500',
                                                    fontSize: '0.85rem',
                                                    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                                                    cursor: 'text'
                                                };

                                                if (isSi) {
                                                    cellStyle.backgroundColor = '#dcfce7'; // green-100
                                                    cellStyle.color = '#166534'; // green-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (isNum) {
                                                    cellStyle.backgroundColor = '#dbeafe'; // blue-100
                                                    cellStyle.color = '#1e40af'; // blue-800
                                                    cellStyle.fontWeight = '700';
                                                    cellStyle.boxShadow = '0 1px 2px rgba(0,0,0,0.05)';
                                                } else if (val !== '') {
                                                    // Any other text
                                                    cellStyle.backgroundColor = '#f3f4f6';
                                                    cellStyle.color = '#374151';
                                                }

                                                return (
                                                    <td key={month.id} className="p-1 border-r border-b border-gray-300 last:border-r-0 align-middle">
                                                        <div className="flex items-center justify-center h-full w-full">
                                                            <input 
                                                                type="text" 
                                                                value={val}
                                                                onChange={(e) => handleCellChange(pName, month.id, e.target.value)}
                                                                className="focus:bg-white focus:ring-2 focus:ring-indigo-200 focus:border-indigo-300 hover:bg-gray-100"
                                                                style={cellStyle}
                                                                placeholder="-"
                                                            />
                                                        </div>
                                                    </td>
                                                );
                                            })}

                                            {/* Visit Date */}
                                            <td className="p-3 border-l border-r border-b border-gray-300 bg-gray-50/20">
                                                <div className="relative flex justify-center">
                                                    <input 
                                                        type="date" 
                                                        value={visitDate}
                                                        onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                        className="bg-transparent text-xs text-center focus:outline-none cursor-pointer font-bold rounded-lg px-2 py-1 transition-all hover:shadow-sm"
                                                        style={{color: visitColor, backgroundColor: visitBg}}
                                                    />
                                                    {!visitDate && <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-gray-300 text-xs">-</div>}
                                                </div>
                                            </td>

                                            {/* Actions */}
                                            <td className="py-3 px-3 text-center border-l border-b border-gray-300">
                                                <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200 transform translate-x-2 group-hover:translate-x-0">
                                                    <button onClick={() => handleSaveRow(pName)} className="text-indigo-600 hover:text-indigo-800 bg-indigo-50 hover:bg-indigo-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Guardar Fila">
                                                        <i className="fas fa-save text-xs"></i>
                                                    </button>
                                                    <button onClick={() => handleDeleteMember(m.id, pName)} className="text-red-400 hover:text-red-600 bg-red-50 hover:bg-red-100 w-8 h-8 rounded-full flex items-center justify-center transition-colors shadow-sm" title="Eliminar">
                                                        <i className="fas fa-trash-alt text-xs"></i>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {members.length === 0 && (
                        <div className="py-24 text-center bg-white">
                            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6 border border-gray-100 shadow-inner">
                                <i className="fas fa-users text-gray-300 text-3xl"></i>
                            </div>
                            <h3 className="text-xl font-bold text-gray-800 mb-2">Este grupo está vacío</h3>
                            <p className="text-gray-500 max-w-xs mx-auto">Utiliza la barra de búsqueda superior para agregar publicadores a este grupo.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;
